package com.alpharip.staffmod.AuditFindingsBoard;import java.util.*;
public final class AuditFindingsRegistry {private final List<AuditFinding> findings=new ArrayList<AuditFinding>();public synchronized void add(AuditFinding f){if(f==null)throw new IllegalArgumentException("Finding required");if(get(f.getId())!=null)throw new IllegalArgumentException("Duplicate finding ID");findings.add(f);}public synchronized AuditFinding get(String id){if(id==null)return null;for(AuditFinding f:findings)if(f.getId().equals(id))return f;return null;}public synchronized boolean remove(String id){for(int i=0;i<findings.size();i++)if(findings.get(i).getId().equals(id)){findings.remove(i);return true;}return false;}public synchronized List<AuditFinding> getAll(){return Collections.unmodifiableList(new ArrayList<AuditFinding>(findings));}public synchronized int size(){return findings.size();}public synchronized void replaceAll(List<AuditFinding> values){findings.clear();if(values!=null)for(AuditFinding f:values)if(f!=null&&get(f.getId())==null)findings.add(f);} }
